export function getMockCourses(params: CourseQueryParams): StrapiResponse<CourseCard[]> {
  let filtered = [...MOCK_COURSES];

  if (params.search) {
    const s = params.search.toLowerCase();
    filtered = filtered.filter(c => 
      c.title.toLowerCase().includes(s) || 
      (c.shortDescription && c.shortDescription.toLowerCase().includes(s))
    );
  }

  if (params.category && params.category !== 'all') {
    filtered = filtered.filter(c => c.category?.slug === params.category);
  }

  if (params.difficulty && (params.difficulty as string) !== 'all') {
    filtered = filtered.filter(c => c.difficulty === params.difficulty);
  }

  if (params.sort) {
    switch (params.sort) {
      case 'popular':
        filtered.sort((a, b) => (b.totalStudents || 0) - (a.totalStudents || 0));
        break;
      case 'rating':
        filtered.sort((a, b) => (b.averageRating || 0) - (a.averageRating || 0));
        break;
      case 'price-asc':
        filtered.sort((a, b) => a.price - b.price);
        break;
      case 'price-desc':
        filtered.sort((a, b) => b.price - a.price);
        break;
      case 'newest':
      default:
        filtered.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
        break;
    }
  }

  const page = params.page || 1;
  const pageSize = params.pageSize || 12;
  const total = filtered.length;
  const pageCount = Math.ceil(total / pageSize);
  const start = (page - 1) * pageSize;
  const paged = filtered.slice(start, start + pageSize);

  const courseCards: CourseCard[] = paged.map(c => ({
    id: c.id,
    title: c.title,
    slug: c.slug,
    shortDescription: c.shortDescription,
    thumbnail: c.thumbnail,
    price: c.price,
    originalPrice: c.originalPrice,
    difficulty: c.difficulty,
    duration: c.duration,
    totalStudents: c.totalStudents,
    averageRating: c.averageRating,
    totalReviews: c.totalReviews,
    category: c.category ? {
      id: c.category.id,
      name: c.category.name,
      slug: c.category.slug,
      color: c.category.color,
    } : null,
    instructor: c.instructor ? {
      id: c.instructor.id,
      name: c.instructor.name,
      avatar: c.instructor.avatar,
    } : null,
  }));

  return {
    data: courseCards,
    meta: {
      pagination: {
        page,
        pageSize,
        pageCount,
        total,
      },
    },
  };
}

export function getMockFeaturedCourses(): CourseCard[] {
  const sorted = [...MOCK_COURSES].sort((a, b) => (b.totalStudents || 0) - (a.totalStudents || 0));
  return sorted.slice(0, 4).map(c => ({
    id: c.id,
    title: c.title,
    slug: c.slug,
    shortDescription: c.shortDescription,
    thumbnail: c.thumbnail,
    price: c.price,
    originalPrice: c.originalPrice,
    difficulty: c.difficulty,
    duration: c.duration,
    totalStudents: c.totalStudents,
    averageRating: c.averageRating,
    totalReviews: c.totalReviews,
    category: c.category ? {
      id: c.category.id,
      name: c.category.name,
      slug: c.category.slug,
      color: c.category.color,
    } : null,
    instructor: c.instructor ? {
      id: c.instructor.id,
      name: c.instructor.name,
      avatar: c.instructor.avatar,
    } : null,
  }));
}

export function getMockCourseBySlug(slug: string): Course | null {
  return MOCK_COURSES.find(c => c.slug === slug) || null;
}

export function getMockLessonBySlug(slug: string): Lesson | null {
  for (const course of MOCK_COURSES) {
    const lesson = course.lessons.find(l => l.slug === slug);
    if (lesson) return lesson as unknown as Lesson;
  }
  return null;
}

export function getMockQuizById(id: string): Quiz | null {
  return MOCK_QUIZZES.find(q => String(q.id) === id || q.documentId === id) || null;
}
